/** Raw health of one captured page, persisted verbatim as `<pageKey>.health.json`. */
export type HealthSnapshot = {
  /** Final main-document HTTP status, null when no response arrived. */
  status: number | null;
  finalUrl: string;
  criticalError: boolean;
  consoleErrors: string[];
  /** Subresource HTTP >= 400 responses, or `status: null` for transport failures. */
  failedRequests: { url: string; status: number | null }[];
  /** HTTP resources referenced by a final HTTPS document. */
  mixedContent: string[];
};

export type Severity = "warning" | "failure";

export type HealthFinding = {
  severity: Severity;
  kind: "status" | "critical-error" | "console-error" | "failed-request" | "mixed-content";
  detail: string;
};

export class HealthFormatError extends Error {
  constructor(field: string, detail: string) {
    super(`health: ${field}: ${detail}`);
    this.name = "HealthFormatError";
  }
}

export const CRITICAL_ERROR_PHRASE = "There has been a critical error on this website";

type FailedRequest = HealthSnapshot["failedRequests"][number];
const requestKey = (r: FailedRequest) => `${r.status ?? ""} ${r.url}`;
const sortedUnique = (xs: string[]) => [...new Set(xs)].sort();

/** Deduplicates and deterministically sorts every list, keeping query strings and statuses distinct. */
export function normalizeHealth(h: HealthSnapshot): HealthSnapshot {
  const requests = new Map(h.failedRequests.map((r) => [JSON.stringify([r.url, r.status]), { url: r.url, status: r.status }]));
  return {
    status: h.status,
    finalUrl: h.finalUrl,
    criticalError: h.criticalError,
    consoleErrors: sortedUnique(h.consoleErrors),
    failedRequests: [...requests.values()].sort((a, b) =>
      a.url < b.url ? -1 : a.url > b.url ? 1 : (a.status ?? -1) - (b.status ?? -1),
    ),
    mixedContent: sortedUnique(h.mixedContent),
  };
}

/**
 * Findings for `actual`, relative to an optional baseline. HTTP >= 400, critical errors and mixed
 * content always fail. Console errors and failed URL/status pairs already in the baseline are
 * warnings; new ones fail; ones only in the baseline are not reported.
 */
export function evaluateHealth(actual: HealthSnapshot, baseline: HealthSnapshot | null): HealthFinding[] {
  const findings: HealthFinding[] = [];
  const fail = (kind: HealthFinding["kind"], detail: string) => findings.push({ severity: "failure", kind, detail });
  const known = (seen: boolean): Severity => (seen ? "warning" : "failure");

  if (actual.status === null) fail("status", `no HTTP response for ${actual.finalUrl}`);
  else if (actual.status >= 400) fail("status", `HTTP ${actual.status} for ${actual.finalUrl}`);
  if (actual.criticalError) fail("critical-error", `page shows "${CRITICAL_ERROR_PHRASE}"`);
  for (const url of sortedUnique(actual.mixedContent)) fail("mixed-content", `insecure resource ${url}`);

  const oldConsole = new Set(baseline?.consoleErrors);
  for (const message of sortedUnique(actual.consoleErrors)) {
    findings.push({ severity: known(oldConsole.has(message)), kind: "console-error", detail: message });
  }
  const oldRequests = new Set(baseline?.failedRequests.map(requestKey));
  for (const r of normalizeHealth(actual).failedRequests) {
    const what = r.status === null ? "transport failure" : `HTTP ${r.status}`;
    findings.push({ severity: known(oldRequests.has(requestKey(r))), kind: "failed-request", detail: `${what} ${r.url}` });
  }
  return findings;
}

/** Validates parsed `.health.json` content; throws `HealthFormatError` naming the bad field. */
export function parseHealth(value: unknown): HealthSnapshot {
  const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
  const isStatus = (v: unknown) => v === null || Number.isInteger(v);
  const strings = (v: unknown) => Array.isArray(v) && v.every((s) => typeof s === "string");
  if (!isObj(value)) throw new HealthFormatError("<root>", "must be an object");

  const keys = ["status", "finalUrl", "criticalError", "consoleErrors", "failedRequests", "mixedContent"];
  for (const key of Object.keys(value)) if (!keys.includes(key)) throw new HealthFormatError(key, "unknown key");
  const { status, finalUrl, criticalError, consoleErrors, failedRequests, mixedContent } = value;
  if (!isStatus(status)) throw new HealthFormatError("status", "must be an integer or null");
  if (typeof finalUrl !== "string") throw new HealthFormatError("finalUrl", "must be a string");
  if (typeof criticalError !== "boolean") throw new HealthFormatError("criticalError", "must be a boolean");
  if (!strings(consoleErrors)) throw new HealthFormatError("consoleErrors", "must be a list of strings");
  const requestOk = (r: unknown) => isObj(r) && Object.keys(r).length === 2 && typeof r.url === "string" && isStatus(r.status);
  if (!Array.isArray(failedRequests) || !failedRequests.every(requestOk)) {
    throw new HealthFormatError("failedRequests", "must be a list of {url, status}");
  }
  if (!strings(mixedContent)) throw new HealthFormatError("mixedContent", "must be a list of strings");
  return normalizeHealth(value as HealthSnapshot);
}
import { existsSync, mkdirSync } from "node:fs";
import { resolve, join } from "node:path";
import { combineMasks, MaskSelectorError, openCaptureSession, type CaptureResult, type CaptureSession, type SessionOptions } from "../capture.ts";
import { EnvError, readR2Config } from "../env.ts";
import { evaluateHealth } from "../health.ts";
import { loadSites, pageKey, SitesConfigError, type Site } from "../sites.ts";
import { createStore, isRunId, type Store } from "../store.ts";
import { artifactPath, ReportError, viewportNames } from "../report/manifest.ts";
import { reportStatus } from "../report/html.ts";
import { saveArtifact } from "../report/writer.ts";
import type { RunReport, ViewportResult } from "../report/model.ts";

export type Command = "baseline" | "check" | "approve";
export type ExitCode = 0 | 1 | 2;
export type RunOptions = { runsDir?: string; runId?: string; browser?: SessionOptions; log?: (message: string) => void };
export type CommandResult = { exitCode: ExitCode; report?: RunReport; runDir?: string; localPath?: string; url?: string };
export class UsageError extends Error {}
export type Arguments = { target: string; pagePath?: string; sitesFile?: string };

export function parseArgs(command: Command, args: string[]): Arguments {
  if (!["baseline", "check", "approve"].includes(command)) throw new UsageError("unknown command");
  const positional: string[] = [];
  let sitesFile: string | undefined;
  for (let i = 0; i < args.length; i++) {
    const value = args[i]!;
    if (value === "--sites") {
      if (sitesFile !== undefined || !args[i + 1] || args[i + 1]!.startsWith("--")) throw new UsageError("--sites requires one file, supplied once");
      sitesFile = args[++i];
    } else if (value.startsWith("-")) throw new UsageError("unsupported command option");
    else positional.push(value);
  }
  if (positional.length < 1 || positional.length > (command === "approve" ? 2 : 1)) throw new UsageError(`usage: ${command} <${command === "approve" ? "slug> [pagePath]" : "slug|all>"} [--sites file]`);
  const target = positional[0]!;
  if (command === "approve" && target === "all") throw new UsageError("approve requires one site slug; all is not supported");
  return { target, ...(positional[1] !== undefined ? { pagePath: positional[1] } : {}), ...(sitesFile !== undefined ? { sitesFile } : {}) };
}
export function selectSites(sites: Site[], target: string): Site[] {
  if (target === "all") return sites;
  const site = sites.find(s => s.slug === target);
  if (!site) throw new UsageError("unknown site slug");
  return [site];
}

/** Unknown errors never expose storage endpoints, credentials, bucket names or raw SDK messages. */
export function safeError(error: unknown): string {
  if (error instanceof UsageError || error instanceof SitesConfigError || error instanceof EnvError || error instanceof MaskSelectorError || error instanceof ReportError) return error.message;
  const code = (error as { code?: unknown } | null)?.code;
  return typeof code === "string" && /^[A-Za-z0-9_]{1,64}$/.test(code) ? `operation failed (${code})` : "operation failed";
}
export const configurationError = (error: unknown) => error instanceof UsageError || error instanceof SitesConfigError || error instanceof EnvError || error instanceof MaskSelectorError;

/** Harness seam: supply a real scoped Store and browser/run options; CLI has no scope/TLS bypass flags. */
export async function dispatch(command: Command, args: string[], options: RunOptions & { store?: Store } = {}): Promise<ExitCode> {
  const log = options.log ?? console.log;
  try {
    const parsed = parseArgs(command, args);
    const sites = selectSites(loadSites(parsed.sitesFile), parsed.target);
    if (parsed.pagePath !== undefined && !sites[0]!.pages.some(p => p.path === parsed.pagePath)) throw new UsageError("requested page is not in the current site list");
    if (!sites.length) { log("No sites selected."); return 0; }
    const store = options.store ?? createStore({ config: readR2Config() });
    if (command === "baseline") return (await (await import("./baseline.ts")).runBaseline(sites, store, options)).exitCode;
    if (command === "check") return (await (await import("./check.ts")).runCheck(sites, store, options)).exitCode;
    return (await (await import("./approve.ts")).runApprove(sites[0]!, store, { pagePath: parsed.pagePath, log })).exitCode;
  } catch (error) {
    log(`${command}: ${safeError(error)}`);
    return configurationError(error) ? 2 : 1;
  }
}

type ConsumeCapture = (site: Site, key: string, capture: CaptureResult, result: ViewportResult, runDir: string) => Promise<void>;
/** Shared sequential production capture path, with one browser and all selectors preflighted. */
export async function captureSelection(sites: Site[], options: RunOptions, consume: ConsumeCapture): Promise<Required<Pick<CommandResult, "report" | "runDir" | "exitCode">>> {
  const runId = options.runId ?? new Date().toISOString().replaceAll(":", "-");
  if (!isRunId(runId)) throw new UsageError("runId must be a canonical timestamp");
  const runDir = resolve(options.runsDir ?? "runs", runId);
  // Do not silently mix local files from separate executions sharing a timestamp.
  if (existsSync(runDir)) throw new ReportError("run directory already exists; use a fresh run ID");
  mkdirSync(runDir, { recursive: true });
  const report: RunReport = { runId, sites: [] };
  let session: CaptureSession | undefined;
  let operationalFailure = false;
  try {
    try { session = await openCaptureSession(options.browser); }
    catch { operationalFailure = true; }
    if (session) await session.validateMasks(sites.flatMap(s => s.pages.flatMap(p => combineMasks(s, p))));
    for (const site of sites) {
      const result = { slug: site.slug, url: site.url, pages: [] as RunReport["sites"][number]["pages"] };
      report.sites.push(result);
      for (const page of site.pages) {
        const key = pageKey(page.path);
        const viewports = {} as Record<"desktop" | "mobile", ViewportResult>;
        result.pages.push({ path: page.path, pageKey: key, viewports });
        for (const name of viewportNames) {
          const trace = artifactPath("traces", site.slug, name, key, "trace.zip");
          let capture: CaptureResult;
          try {
            if (!session) throw new Error("browser unavailable");
            capture = await session.capture({ url: site.url + page.path, viewport: name, masks: combineMasks(site, page), tracePath: join(runDir, trace) });
          } catch (error) {
            if (configurationError(error)) throw error;
            capture = { state: "error", detail: "Browser/capture operation failed.", image: null, health: { status: null, finalUrl: site.url + page.path, criticalError: false, consoleErrors: [], failedRequests: [], mixedContent: [] }, warnings: [], tracePath: null };
          }
          const v: ViewportResult = {
            viewport: name, capture: { state: capture.state, detail: capture.detail },
            visual: { state: "not-compared", detail: null, baseline: null, actual: capture.image ? { width: capture.image.width, height: capture.image.height } : null, ratio: null, allowance: site.max_diff_pixel_ratio },
            health: evaluateHealth(capture.health, null), warnings: capture.warnings, artifacts: {},
          };
          viewports[name] = v;
          if (capture.tracePath && existsSync(join(runDir, trace))) v.artifacts.trace = trace;
          try {
            const healthPath = artifactPath("actual", site.slug, name, key, "health.json");
            await saveArtifact(runDir, healthPath, JSON.stringify(capture.health, null, 2) + "\n");
            v.artifacts.actualHealth = healthPath;
            if (capture.state === "captured" && capture.image) {
              const pngPath = artifactPath("actual", site.slug, name, key, "png");
              await saveArtifact(runDir, pngPath, capture.image.png);
              v.artifacts.actualPng = pngPath;
            } else if (capture.state === "captured") {
              v.capture = { state: "error", detail: "Capture is incomplete: PNG is unavailable." };
            }
            await consume(site, key, capture, v, runDir);
          } catch (error) {
            if (configurationError(error)) throw error;
            v.visual.state = "error";
            v.visual.detail = `Artifact/storage ${safeError(error)}`;
          }
          (options.log ?? console.log)(`${site.slug} ${page.path} ${name}: capture ${v.capture.state}, visual ${v.visual.state}, health ${v.health.some(h => h.severity === "failure") ? "failure" : v.health.length ? "warning" : "pass"}${v.visual.detail ? ` — ${v.visual.detail}` : ""}`);
        }
      }
    }
  } finally {
    if (session) try { await session.close(); } catch { operationalFailure = true; (options.log ?? console.log)("Browser close failed."); }
  }
  return { report, runDir, exitCode: operationalFailure || ["failure", "blocked"].includes(reportStatus(report)) ? 1 : 0 };
}
import { join } from "node:path";
import type { Site } from "../sites.ts";
import type { Store } from "../store.ts";
import { artifactPath } from "../report/manifest.ts";
import { captureSelection, dispatch, type CommandResult, type RunOptions } from "./common.ts";

export async function runBaseline(sites: Site[], store: Store, options: RunOptions = {}): Promise<CommandResult> {
  if (!sites.length) return { exitCode: 0 };
  const result = await captureSelection(sites, options, async (site, key, capture, v, runDir) => {
    if (v.capture.state !== "captured" || !capture.image || !v.artifacts.actualPng || !v.artifacts.actualHealth) return;
    // Both local artifacts must be ready before replacing either remote object. R2 pairs are not transactional.
    const png = await Bun.file(join(runDir, v.artifacts.actualPng)).arrayBuffer();
    const health = await Bun.file(join(runDir, v.artifacts.actualHealth)).arrayBuffer();
    const base = artifactPath("baseline", site.slug, v.viewport, key, "png").replace(/^baseline\//, "baselines/");
    await store.put(base, new Blob([png], { type: "image/png" }));
    await store.put(base.replace(/\.png$/, ".health.json"), new Blob([health], { type: "application/json" }));
  });
  (options.log ?? console.log)(`Baseline artifacts: ${result.runDir}`);
  return result;
}

if (import.meta.main) process.exitCode = await dispatch("baseline", process.argv.slice(2));

### D3 — Bounded capture and read-only browsing

`src/capture.ts` owns browser/context lifecycle and exposes the same capture path to baseline/check/tests. Install health listeners before navigation. Start tracing with screenshots/snapshots/sources, no video, and save a trace for each attempted capture even on failure; close contexts/browser in `finally`.

Navigate with a finite timeout (30 seconds), wait for load and then network idle with its own **15-second cap**. An idle timeout on an otherwise loaded page is a reported readiness warning, not automatically a blocked site. Scroll incrementally to the bottom and back to the top to trigger lazy loading, with a finite time/iteration limit (15 seconds); then wait boundedly for fonts/images to settle. Infinite scroll/never-settling resources must not hang a run. Surface readiness-limit warnings rather than claiming a fully settled capture.

Disable CSS animations, transitions, smooth scrolling and caret, and use screenshot animation disabling. Combine site and page masks and pass locators through Playwright's `mask` option. Enforce CSS selector syntax (not arbitrary Playwright selector engines); invalid syntax is configuration exit 2. A valid selector matching nothing is a warning, not a fake mask success. Capture returns PNG dimensions and raw health; never infer screenshot height from the viewport.

For the locked read-only scope, block service workers and abort page-originated non-GET HTTP requests (including POST/beacon); never click forms or invoke update/admin flows. Record policy-aborted requests distinctly in capture warnings so they are not mistaken for server-side asset failures. Ordinary browser asset GETs remain allowed, including cross-origin assets. No TLS bypass on real sites. Test-only WP-CLI mutations occur outside the checker browser, on the disposable local WordPress only. GET-only navigation cannot guarantee a poorly designed remote GET endpoint has no side effects; document that limitation rather than promise more.

### D4 — Raw health and baseline-relative findings

Export the locked health file shape from `src/health.ts` without adding comparison state to persisted raw health:

```ts
type HealthSnapshot = {
  status: number | null; // final main-document response, null if unavailable
  finalUrl: string;
  criticalError: boolean;
  consoleErrors: string[];
  failedRequests: { url: string; status: number | null }[];
  mixedContent: string[];
};
```

Use `null` for transport failures with no HTTP status. Collect console `error` events and uncaught `pageerror`; detect subresource HTTP >=400 through response events (HTTP errors are not Playwright `requestfailed` events), and transport failures through `requestfailed`. Keep failed main-document navigation separate from the subresource failure list. Deduplicate and deterministically sort comparable messages/URL-status pairs without stripping query parameters or normalizing away distinct failures.

`criticalError` recognizes the WordPress phrase “There has been a critical error on this website” case-insensitively in rendered document text. Final HTTP >=400, a critical error, and mixed content are unconditional failures; their presence in a baseline never waives them. On a check, identical baseline console messages and failed-request `{url,status}` pairs are **warnings**, new ones **failures**. Removed findings disappear. Warnings alone keep exit 0. Persist the complete raw snapshot, not only the new failures.

Mixed content means attempted/included HTTP subresources on the **final HTTPS document**, not ordinary HTTP hyperlinks. Combine request observation, browser mixed-content diagnostics and a DOM resource-attribute sweep (`src`, resource `href`, `srcset`, frames/media/objects) so Chromium blocking/upgrading an HTTP resource before an observable failed request does not silently pass. Test an actual HTTP asset reference on the Bun HTTPS fixture; don't equate any console error with mixed content. No active mixed-content weakening browser flags.

A page that cannot navigate at all (DNS/refused connection/TLS/navigation timeout), a 403, or a positively identified challenge/interstitial is `blocked`, carries the reason, counts as failure and does not terminate the remaining pages/sites. Detect challenge responses using explicit known challenge markers/headers and interstitial structure, not every page containing the words “Cloudflare” or “captcha”; a normal form CAPTCHA is not a blocked site. A 404 is a health failure, not “blocked.” Missing Chromium/browser crashes are operational failures, not fabricated site bot-blocking findings.

